import React, { useEffect, useState } from "react";
import { v4 as uuidv4 } from 'uuid'; // Benzersiz ID için
import { Question, Message, DomainStatus } from './types'; // Tipleri merkezi yerden al

// Ayrılmış Bileşenleri Import Et
import Header from './components/Header';
import ChatPanel from './components/ChatPanel';
import Sidebar from './components/Sidebar';


const App: React.FC = () => {
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentQuestionId, setCurrentQuestionId] = useState<number | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [domainStatuses, setDomainStatuses] = useState<DomainStatus[]>([]);
  const [overallScore, setOverallScore] = useState<number>(0);
  const [isLoading, setIsLoading] = useState<boolean>(true); // Yüklenme durumu

  useEffect(() => {
    // ... (Başlangıçtaki fetch mantığı neredeyse aynı, sadece mesajlara ID ekliyoruz)
    fetch("http://localhost:3001/questions")
      .then((res) => res.json())
      .then((data: Question[]) => {
        setQuestions(data);
        if (data.length > 0) {
          const firstQuestion = data[0];
          setCurrentQuestionId(firstQuestion.id);
          setMessages([{
            id: uuidv4(),
            sender: 'AI',
            text: 'Welcome!',
            type: 'question',
            question: firstQuestion
          }]);
          // ... (initialDomains mantığı aynı)
        }
      })
      .catch((err) => console.error("Error fetching questions:", err))
      .finally(() => setIsLoading(false));
  }, []);

  const handleSendMessage = async (prompt: string) => {
    if (!currentQuestionId || isLoading) return;
    setIsLoading(true);

    const userMessage: Message = {
      id: uuidv4(),
      sender: 'User',
      text: prompt,
      type: 'user_response'
    };
    setMessages(prev => [...prev, userMessage]);

    try {
      const res = await fetch("http://localhost:3001/ask", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ prompt, previous_question_id: currentQuestionId }),
      });
      const apiResponse = await res.json();
      
      // YENİ MANTIK: Gelen cevabı işle
      
      // 1. Görev Onay Mesajını oluştur
      const taskMessage: Message = {
          id: uuidv4(),
          sender: 'AI',
          text: apiResponse.task, // API'den gelen task metni
          type: 'task_confirmation'
      };
      
      const nextQuestion = questions.find(q => q.id === apiResponse.next_question_id);
      
      // 2. Bir sonraki soru mesajını oluştur
      const nextQuestionMessage: Message = {
        id: uuidv4(),
        sender: 'AI',
        text: 'Here is the next question.',
        type: 'question',
        question: nextQuestion,
        // YENİ: Bir sonraki soruya, cevaplanan sorunun yorumunu ekle
        ai_comment: apiResponse.comment 
      };

      // 3. İki yeni mesajı birden state'e ekle
      setMessages(prev => [...prev, taskMessage, nextQuestionMessage]);
      setCurrentQuestionId(apiResponse.next_question_id);

      // ... (Domain ve skor güncelleme mantığı aynı kalıyor)
      
    } catch (err) {
      console.error("Error sending message:", err);
      // Hata mesajı ekle
      setMessages(prev => [...prev, { id: uuidv4(), sender: 'AI', text: "Sorry, an error occurred.", type: 'error' }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="bg-[#0f0f23] text-gray-200 font-sans h-screen overflow-hidden flex flex-col">
      <Header />
      <div className="flex flex-1 overflow-hidden">
        <ChatPanel 
          messages={messages} 
          onSendMessage={handleSendMessage} 
          isLoading={isLoading} 
        />
        <Sidebar 
          statuses={domainStatuses} 
          overallScore={overallScore} 
        />
      </div>
    </div>
  );
};

export default App;
